// One-off content build (same spirit as build-questions.js - NOT part of the running
// app). Populates the three categories that shipped as empty [] placeholders
// (science, politics, new-zealand) and expands literature from its 88-entry
// redistribution placeholder up to the same ~400-entry size as the other sets.
//
// Rerun after editing the arrays below:  node server/build-questions-extra.js
//
// Compact source form per question:  ["question text", ["opt A", "opt B", "opt C"], correctIndex 0-2, difficulty 1-5]
//   difficulty bands used by the game (server/rooms.js difficultyBand): easy = 1-2, medium = 3, hard = 4-5.
//   Aim for a spread so the host's fixed-difficulty picker has a real pool in every band.
//
// All four files are written fresh from the arrays below. The literature set folds in
// LITERATURE_ORIGINAL (the ~80 entries that shipped in the first literature.json, minus a
// handful of stray maths/astronomy items that never belonged in a Literature category).

const fs = require('fs');
const path = require('path');
const OUT_DIR = path.join(__dirname, 'questions');

function expand(rows) {
  return rows.map(([q, opts, correctIdx, difficulty], i) => {
    if (!Array.isArray(opts) || opts.length !== 3) throw new Error(`row ${i}: need exactly 3 options - ${q}`);
    if (correctIdx < 0 || correctIdx > 2) throw new Error(`row ${i}: correctIndex out of range - ${q}`);
    if (!Number.isInteger(difficulty) || difficulty < 1 || difficulty > 5) throw new Error(`row ${i}: bad difficulty - ${q}`);
    return { q, options: { A: opts[0], B: opts[1], C: opts[2] }, correct: 'ABC'[correctIdx], difficulty };
  });
}

function dedupe(list) {
  const seen = new Set();
  const out = [];
  for (const item of list) {
    const key = item.q.toLowerCase().replace(/\s+/g, ' ').trim();
    if (seen.has(key)) continue;
    seen.add(key);
    // sanity: correct answer must be one of the three options and options must be distinct
    const opts = [item.options.A, item.options.B, item.options.C];
    if (new Set(opts.map(o => String(o).toLowerCase().trim())).size !== 3) {
      console.warn('  ! duplicate/blank option, skipping:', item.q);
      continue;
    }
    out.push(item);
  }
  return out;
}

function build(name, rows) {
  let list = dedupe(expand(rows));
  const bands = [0, 0, 0];
  for (const q of list) bands[q.difficulty <= 2 ? 0 : q.difficulty === 3 ? 1 : 2]++;
  fs.writeFileSync(path.join(OUT_DIR, name), JSON.stringify(list, null, 2) + '\n');
  console.log(`${name.padEnd(18)} ${String(list.length).padStart(4)} entries   bands [easy ${bands[0]} / med ${bands[1]} / hard ${bands[2]}]`);
}

